//! Go standard-library behaviour that block D00.2 depends on and that Rust's std does not
//! reproduce exactly (ON-DEMAND tool code, Go 1.25.12).
//!
//! go-file: $GOROOT/src/unicode/letter.go
//! go-file: $GOROOT/src/unicode/digit.go
//!
//! `unicode_tables.rs` holds Go's category tables (generated by tracker `govec/cmd/rsgen`).

pub mod unicode_tables;

/// `unicode.Range16`.
pub struct Range16 {
    pub lo: u16,
    pub hi: u16,
    pub stride: u16,
}

/// `unicode.Range32`.
pub struct Range32 {
    pub lo: u32,
    pub hi: u32,
    pub stride: u32,
}

/// `unicode.RangeTable`.
pub struct RangeTable {
    pub r16: &'static [Range16],
    pub r32: &'static [Range32],
    pub latin_offset: usize,
}

/// `unicode.MaxLatin1`.
const MAX_LATIN1: u32 = 0xff;

// go-std: unicode.is16 L1
fn is16(ranges: &[Range16], r: u16) -> bool {
    if ranges.len() <= 18 || r <= MAX_LATIN1 as u16 {
        for range in ranges {
            if r < range.lo {
                return false;
            }
            if r <= range.hi {
                return range.stride == 1 || (r - range.lo).is_multiple_of(range.stride);
            }
        }
        return false;
    }
    // binary search over ranges
    let (mut lo, mut hi) = (0usize, ranges.len());
    while lo < hi {
        let m = lo + (hi - lo) / 2;
        let range = &ranges[m];
        if range.lo <= r && r <= range.hi {
            return range.stride == 1 || (r - range.lo).is_multiple_of(range.stride);
        }
        if r < range.lo {
            hi = m;
        } else {
            lo = m + 1;
        }
    }
    false
}

// go-std: unicode.is32 L1
fn is32(ranges: &[Range32], r: u32) -> bool {
    if ranges.len() <= 18 {
        for range in ranges {
            if r < range.lo {
                return false;
            }
            if r <= range.hi {
                return range.stride == 1 || (r - range.lo).is_multiple_of(range.stride);
            }
        }
        return false;
    }
    // binary search over ranges
    let (mut lo, mut hi) = (0usize, ranges.len());
    while lo < hi {
        let m = lo + (hi - lo) / 2;
        let range = &ranges[m];
        if range.lo <= r && r <= range.hi {
            return range.stride == 1 || (r - range.lo).is_multiple_of(range.stride);
        }
        if r < range.lo {
            hi = m;
        } else {
            lo = m + 1;
        }
    }
    false
}

/// `unicode.Is` reports whether the rune is in the specified table of ranges.
// go-std: unicode.Is L1
pub fn is(range_tab: &RangeTable, r: char) -> bool {
    let r = r as u32;
    let r16 = range_tab.r16;
    // Compare as uint32 to correctly handle negative runes.
    if !r16.is_empty() && r <= u32::from(r16[r16.len() - 1].hi) {
        return is16(r16, r as u16);
    }
    let r32 = range_tab.r32;
    if !r32.is_empty() && r >= r32[0].lo {
        return is32(r32, r);
    }
    false
}

/// `unicode.IsOneOf` reports whether the rune is a member of one of the ranges.
// go-std: unicode.IsOneOf L1
pub fn is_one_of(ranges: &[&RangeTable], r: char) -> bool {
    ranges.iter().any(|inside| is(inside, r))
}

/// `unicode.IsDigit` reports whether the rune is a decimal digit.
// go-std: unicode.IsDigit L1
pub fn is_digit(r: char) -> bool {
    if (r as u32) <= MAX_LATIN1 {
        return r.is_ascii_digit();
    }
    is(&unicode_tables::Nd, r)
}

/// `unicode.IsDigit(rune(b))` for a byte of a Go string (`rune(precision[0])`).
// glue: Go rune(byte) conversion
pub fn is_digit_byte(b: u8) -> bool {
    is_digit(char::from(b))
}

/// `strings.ToUpper`: ASCII fast path; other runes use Rust's uppercase mapping when it is a
/// single character (Go's `unicode.ToUpper` is the simple mapping, it never expands a rune).
// go-std: strings.ToUpper L2 (unicode.ToUpper approximated by single-char char::to_uppercase)
pub fn to_upper(s: &str) -> String {
    s.chars()
        .map(|c| {
            if c.is_ascii() {
                return c.to_ascii_uppercase();
            }
            let mut up = c.to_uppercase();
            match (up.next(), up.next()) {
                (Some(u), None) => u,
                _ => c,
            }
        })
        .collect()
}

pub(crate) mod ftoaryu;
mod powers;

/// `utf8.DecodeRune`: the rune at the start of `s` and its width; `(RuneError, 1)` for an
/// invalid or incomplete encoding, `(RuneError, 0)` for empty input.
// go-std: unicode/utf8.DecodeRune L2 (validity by std::str::from_utf8)
pub fn decode_rune(s: &[u8]) -> (char, usize) {
    if s.is_empty() {
        return ('\u{fffd}', 0);
    }
    let want = match s[0] {
        0x00..=0x7f => return (char::from(s[0]), 1),
        0xc2..=0xdf => 2,
        0xe0..=0xef => 3,
        0xf0..=0xf4 => 4,
        _ => return ('\u{fffd}', 1),
    };
    if s.len() >= want
        && let Ok(t) = std::str::from_utf8(&s[..want])
        && let Some(c) = t.chars().next()
    {
        return (c, want);
    }
    ('\u{fffd}', 1)
}

/// `utf8.RuneCount`: invalid bytes count one each.
// go-std: unicode/utf8.RuneCount L2 (via decode_rune)
pub fn rune_count(mut s: &[u8]) -> usize {
    let mut n = 0;
    while !s.is_empty() {
        s = &s[decode_rune(s).1..];
        n += 1;
    }
    n
}

/// `for _, r := range s` over a Go string: an invalid byte yields U+FFFD.
// glue: Go range over a string
pub fn runes(mut s: &[u8]) -> impl Iterator<Item = char> + '_ {
    std::iter::from_fn(move || {
        if s.is_empty() {
            return None;
        }
        let (r, w) = decode_rune(s);
        s = &s[w..];
        Some(r)
    })
}

/// `strconv.IsPrint`: Go's printable runes (letters, marks, numbers, punctuation, symbols
/// and U+0020), from the generated table `IS_PRINT`.
// go-std: strconv.IsPrint L2 (table generated from Go's IsPrint)
pub fn is_print(r: char) -> bool {
    let r = r as u32;
    let t = unicode_tables::IS_PRINT;
    t.binary_search_by(|(lo, hi)| {
        if *hi < r {
            std::cmp::Ordering::Less
        } else if *lo > r {
            std::cmp::Ordering::Greater
        } else {
            std::cmp::Ordering::Equal
        }
    })
    .is_ok()
}
